-- Subscription Management System schema reference (PostgreSQL).
-- Executable Django models and migrations in ../backend/ are authoritative.
-- UUID values are generated by the application; Django auth framework tables are omitted.

CREATE TABLE business_profile (
    id UUID PRIMARY KEY,
    singleton BOOLEAN NOT NULL DEFAULT TRUE UNIQUE CHECK (singleton = TRUE),
    legal_name VARCHAR(200) NOT NULL,
    default_currency CHAR(3) NOT NULL,
    timezone VARCHAR(64) NOT NULL,
    billing_email VARCHAR(254) NOT NULL DEFAULT '',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE account_user (
    id UUID PRIMARY KEY,
    email VARCHAR(254) NOT NULL,
    email_normalized VARCHAR(254) NOT NULL UNIQUE,
    password VARCHAR(128) NOT NULL,
    first_name VARCHAR(150) NOT NULL DEFAULT '',
    last_name VARCHAR(150) NOT NULL DEFAULT '',
    role VARCHAR(16) NOT NULL CHECK (role IN ('admin', 'staff', 'customer')),
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    is_staff BOOLEAN NOT NULL DEFAULT FALSE,
    is_superuser BOOLEAN NOT NULL DEFAULT FALSE,
    last_login TIMESTAMPTZ NULL,
    date_joined TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by_id UUID NULL REFERENCES account_user(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE customer (
    id UUID PRIMARY KEY,
    account_user_id UUID NULL UNIQUE REFERENCES account_user(id) ON DELETE SET NULL,
    company_name VARCHAR(200) NOT NULL DEFAULT '',
    contact_name VARCHAR(200) NOT NULL,
    email VARCHAR(254) NOT NULL,
    phone VARCHAR(40) NOT NULL DEFAULT '',
    billing_address TEXT NOT NULL DEFAULT '',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX customer_email_idx ON customer(email);

CREATE TABLE product (
    id UUID PRIMARY KEY,
    name VARCHAR(200) NOT NULL,
    product_type VARCHAR(24) NOT NULL,
    sales_price NUMERIC(14,2) NOT NULL CHECK (sales_price >= 0),
    cost_price NUMERIC(14,2) NOT NULL DEFAULT 0 CHECK (cost_price >= 0),
    currency CHAR(3) NOT NULL,
    notes TEXT NOT NULL DEFAULT '',
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE product_variant (
    id UUID PRIMARY KEY,
    product_id UUID NOT NULL REFERENCES product(id) ON DELETE RESTRICT,
    name VARCHAR(160) NOT NULL,
    price_adjustment NUMERIC(14,2) NOT NULL DEFAULT 0,
    currency CHAR(3) NOT NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    UNIQUE (product_id, name)
);

CREATE TABLE plan (
    id UUID PRIMARY KEY,
    name VARCHAR(200) NOT NULL,
    interval_unit VARCHAR(12) NOT NULL CHECK (interval_unit IN ('daily', 'weekly', 'monthly', 'yearly')),
    interval_count SMALLINT NOT NULL DEFAULT 1 CHECK (interval_count > 0),
    price NUMERIC(14,2) NOT NULL CHECK (price >= 0),
    currency CHAR(3) NOT NULL,
    minimum_quantity INTEGER NOT NULL DEFAULT 1 CHECK (minimum_quantity > 0),
    available_from DATE NULL,
    available_until DATE NULL,
    end_policy VARCHAR(24) NOT NULL CHECK (end_policy IN ('close_at_end', 'renew_until_closed')),
    allow_pause BOOLEAN NOT NULL DEFAULT FALSE,
    allow_renewal BOOLEAN NOT NULL DEFAULT TRUE,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    CHECK (available_until IS NULL OR available_from IS NULL OR available_until >= available_from),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE tax_rule (
    id UUID PRIMARY KEY,
    name VARCHAR(160) NOT NULL,
    rate_percent NUMERIC(7,4) NOT NULL CHECK (rate_percent >= 0 AND rate_percent <= 100),
    active_from DATE NULL,
    active_until DATE NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    CHECK (active_until IS NULL OR active_from IS NULL OR active_until >= active_from),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE discount_rule (
    id UUID PRIMARY KEY,
    name VARCHAR(160) NOT NULL,
    discount_type VARCHAR(12) NOT NULL CHECK (discount_type IN ('fixed', 'percentage')),
    value NUMERIC(14,4) NOT NULL CHECK (value > 0),
    currency CHAR(3) NULL,
    minimum_purchase NUMERIC(14,2) NOT NULL DEFAULT 0 CHECK (minimum_purchase >= 0),
    minimum_quantity INTEGER NOT NULL DEFAULT 1 CHECK (minimum_quantity > 0),
    scope VARCHAR(24) NOT NULL CHECK (scope IN ('products', 'whole_subscription')),
    starts_at TIMESTAMPTZ NULL,
    ends_at TIMESTAMPTZ NULL,
    maximum_uses INTEGER NULL CHECK (maximum_uses IS NULL OR maximum_uses > 0),
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    CHECK ((discount_type = 'fixed' AND currency IS NOT NULL) OR discount_type = 'percentage'),
    CHECK (discount_type <> 'percentage' OR value <= 100),
    CHECK (ends_at IS NULL OR starts_at IS NULL OR ends_at >= starts_at),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE discount_rule_product (
    id UUID PRIMARY KEY,
    discount_rule_id UUID NOT NULL REFERENCES discount_rule(id) ON DELETE CASCADE,
    product_id UUID NOT NULL REFERENCES product(id) ON DELETE RESTRICT,
    UNIQUE (discount_rule_id, product_id)
);

CREATE TABLE quote_template (
    id UUID PRIMARY KEY,
    name VARCHAR(160) NOT NULL,
    validity_days INTEGER NOT NULL CHECK (validity_days > 0),
    payment_terms VARCHAR(200) NOT NULL DEFAULT '',
    created_by_id UUID NULL REFERENCES account_user(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE quote_template_line (
    id UUID PRIMARY KEY,
    template_id UUID NOT NULL REFERENCES quote_template(id) ON DELETE CASCADE,
    line_number INTEGER NOT NULL CHECK (line_number > 0),
    product_id UUID NOT NULL REFERENCES product(id) ON DELETE RESTRICT,
    variant_id UUID NULL REFERENCES product_variant(id) ON DELETE RESTRICT,
    plan_id UUID NULL REFERENCES plan(id) ON DELETE RESTRICT,
    description VARCHAR(500) NOT NULL,
    quantity NUMERIC(12,3) NOT NULL DEFAULT 1 CHECK (quantity > 0),
    UNIQUE (template_id, line_number)
);

CREATE TABLE quote (
    id UUID PRIMARY KEY,
    number VARCHAR(40) NOT NULL UNIQUE,
    customer_id UUID NOT NULL REFERENCES customer(id) ON DELETE RESTRICT,
    template_id UUID NULL REFERENCES quote_template(id) ON DELETE SET NULL,
    status VARCHAR(16) NOT NULL CHECK (status IN ('draft', 'quotation', 'confirmed', 'expired', 'cancelled')),
    valid_until DATE NULL,
    start_date DATE NOT NULL,
    expiry_date DATE NULL,
    payment_terms VARCHAR(200) NOT NULL DEFAULT '',
    currency CHAR(3) NOT NULL,
    subtotal NUMERIC(14,2) NOT NULL DEFAULT 0 CHECK (subtotal >= 0),
    tax_total NUMERIC(14,2) NOT NULL DEFAULT 0 CHECK (tax_total >= 0),
    discount_total NUMERIC(14,2) NOT NULL DEFAULT 0 CHECK (discount_total >= 0),
    total NUMERIC(14,2) NOT NULL DEFAULT 0 CHECK (total >= 0),
    created_by_id UUID NULL REFERENCES account_user(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (expiry_date IS NULL OR expiry_date >= start_date)
);
CREATE INDEX quote_customer_status_idx ON quote(customer_id, status);

CREATE TABLE quote_line (
    id UUID PRIMARY KEY,
    quote_id UUID NOT NULL REFERENCES quote(id) ON DELETE CASCADE,
    line_number INTEGER NOT NULL CHECK (line_number > 0),
    product_id UUID NULL REFERENCES product(id) ON DELETE SET NULL,
    variant_id UUID NULL REFERENCES product_variant(id) ON DELETE SET NULL,
    plan_id UUID NULL REFERENCES plan(id) ON DELETE SET NULL,
    description VARCHAR(500) NOT NULL,
    quantity NUMERIC(12,3) NOT NULL CHECK (quantity > 0),
    unit_price NUMERIC(14,2) NOT NULL CHECK (unit_price >= 0),
    currency CHAR(3) NOT NULL,
    subtotal NUMERIC(14,2) NOT NULL CHECK (subtotal >= 0),
    tax_total NUMERIC(14,2) NOT NULL DEFAULT 0 CHECK (tax_total >= 0),
    discount_total NUMERIC(14,2) NOT NULL DEFAULT 0 CHECK (discount_total >= 0),
    total NUMERIC(14,2) NOT NULL CHECK (total >= 0),
    UNIQUE (quote_id, line_number)
);

CREATE TABLE quote_line_tax (
    id UUID PRIMARY KEY,
    quote_line_id UUID NOT NULL REFERENCES quote_line(id) ON DELETE CASCADE,
    tax_rule_id UUID NULL REFERENCES tax_rule(id) ON DELETE SET NULL,
    name_snapshot VARCHAR(160) NOT NULL,
    rate_percent_snapshot NUMERIC(7,4) NOT NULL CHECK (rate_percent_snapshot >= 0),
    amount NUMERIC(14,2) NOT NULL CHECK (amount >= 0)
);

CREATE TABLE subscription (
    id UUID PRIMARY KEY,
    number VARCHAR(40) NOT NULL UNIQUE,
    customer_id UUID NOT NULL REFERENCES customer(id) ON DELETE RESTRICT,
    quote_id UUID NULL UNIQUE REFERENCES quote(id) ON DELETE SET NULL,
    plan_id UUID NOT NULL REFERENCES plan(id) ON DELETE RESTRICT,
    status VARCHAR(16) NOT NULL CHECK (status IN ('confirmed', 'active', 'paused', 'closed')),
    start_date DATE NOT NULL,
    expiry_date DATE NULL,
    next_period_start DATE NULL,
    next_billing_at DATE NULL,
    payment_terms VARCHAR(200) NOT NULL DEFAULT '',
    currency CHAR(3) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (expiry_date IS NULL OR expiry_date >= start_date)
);
CREATE INDEX subscription_due_idx ON subscription(status, next_billing_at);
CREATE INDEX subscription_customer_status_idx ON subscription(customer_id, status);

CREATE TABLE subscription_line (
    id UUID PRIMARY KEY,
    subscription_id UUID NOT NULL REFERENCES subscription(id) ON DELETE RESTRICT,
    line_number INTEGER NOT NULL CHECK (line_number > 0),
    product_id UUID NULL REFERENCES product(id) ON DELETE SET NULL,
    variant_id UUID NULL REFERENCES product_variant(id) ON DELETE SET NULL,
    description VARCHAR(500) NOT NULL,
    quantity NUMERIC(12,3) NOT NULL CHECK (quantity > 0),
    unit_price NUMERIC(14,2) NOT NULL CHECK (unit_price >= 0),
    currency CHAR(3) NOT NULL,
    UNIQUE (subscription_id, line_number)
);

CREATE TABLE subscription_line_tax_rule (
    subscription_line_id UUID NOT NULL REFERENCES subscription_line(id) ON DELETE CASCADE,
    tax_rule_id UUID NOT NULL REFERENCES tax_rule(id) ON DELETE RESTRICT,
    PRIMARY KEY (subscription_line_id, tax_rule_id)
);

CREATE TABLE subscription_event (
    id UUID PRIMARY KEY,
    subscription_id UUID NOT NULL REFERENCES subscription(id) ON DELETE RESTRICT,
    from_status VARCHAR(16) NULL,
    to_status VARCHAR(16) NOT NULL,
    action VARCHAR(32) NOT NULL,
    note TEXT NOT NULL DEFAULT '',
    actor_id UUID NULL REFERENCES account_user(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX subscription_event_history_idx ON subscription_event(subscription_id, created_at);

CREATE TABLE billing_run (
    id UUID PRIMARY KEY,
    business_date DATE NOT NULL,
    status VARCHAR(16) NOT NULL CHECK (status IN ('running', 'completed', 'completed_with_errors', 'failed')),
    triggered_by_id UUID NULL REFERENCES account_user(id) ON DELETE SET NULL,
    started_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    finished_at TIMESTAMPTZ NULL,
    subscriptions_seen INTEGER NOT NULL DEFAULT 0 CHECK (subscriptions_seen >= 0),
    invoices_created INTEGER NOT NULL DEFAULT 0 CHECK (invoices_created >= 0),
    failures INTEGER NOT NULL DEFAULT 0 CHECK (failures >= 0),
    error_summary TEXT NOT NULL DEFAULT ''
);
CREATE INDEX billing_run_date_idx ON billing_run(business_date, started_at);

CREATE TABLE invoice (
    id UUID PRIMARY KEY,
    number VARCHAR(40) NOT NULL UNIQUE,
    customer_id UUID NOT NULL REFERENCES customer(id) ON DELETE RESTRICT,
    subscription_id UUID NOT NULL REFERENCES subscription(id) ON DELETE RESTRICT,
    billing_run_id UUID NULL REFERENCES billing_run(id) ON DELETE SET NULL,
    billing_period_start DATE NOT NULL,
    billing_period_end DATE NOT NULL,
    status VARCHAR(16) NOT NULL CHECK (status IN ('draft', 'confirmed', 'paid', 'cancelled')),
    issue_date DATE NOT NULL,
    due_date DATE NOT NULL,
    currency CHAR(3) NOT NULL,
    customer_name_snapshot VARCHAR(200) NOT NULL,
    customer_email_snapshot VARCHAR(254) NOT NULL,
    billing_address_snapshot TEXT NOT NULL DEFAULT '',
    subtotal NUMERIC(14,2) NOT NULL CHECK (subtotal >= 0),
    tax_total NUMERIC(14,2) NOT NULL DEFAULT 0 CHECK (tax_total >= 0),
    discount_total NUMERIC(14,2) NOT NULL DEFAULT 0 CHECK (discount_total >= 0),
    total NUMERIC(14,2) NOT NULL CHECK (total >= 0),
    confirmed_at TIMESTAMPTZ NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT invoice_one_per_period UNIQUE (subscription_id, billing_period_start),
    CHECK (billing_period_end >= billing_period_start)
);
CREATE INDEX invoice_due_status_idx ON invoice(status, due_date);
CREATE INDEX invoice_customer_date_idx ON invoice(customer_id, issue_date);
CREATE INDEX invoice_subscription_period_idx ON invoice(subscription_id, billing_period_start);

CREATE TABLE invoice_line (
    id UUID PRIMARY KEY,
    invoice_id UUID NOT NULL REFERENCES invoice(id) ON DELETE RESTRICT,
    line_number INTEGER NOT NULL CHECK (line_number > 0),
    line_type VARCHAR(16) NOT NULL CHECK (line_type IN ('product', 'discount')),
    product_id UUID NULL REFERENCES product(id) ON DELETE SET NULL,
    description VARCHAR(500) NOT NULL,
    quantity NUMERIC(12,3) NOT NULL CHECK (quantity > 0),
    unit_price NUMERIC(14,2) NOT NULL CHECK (unit_price >= 0),
    currency CHAR(3) NOT NULL,
    subtotal NUMERIC(14,2) NOT NULL CHECK (subtotal >= 0),
    tax_total NUMERIC(14,2) NOT NULL DEFAULT 0 CHECK (tax_total >= 0),
    discount_total NUMERIC(14,2) NOT NULL DEFAULT 0 CHECK (discount_total >= 0),
    total NUMERIC(14,2) NOT NULL CHECK (total >= 0),
    UNIQUE (invoice_id, line_number)
);

CREATE TABLE invoice_line_tax (
    id UUID PRIMARY KEY,
    invoice_line_id UUID NOT NULL REFERENCES invoice_line(id) ON DELETE RESTRICT,
    tax_rule_id UUID NULL REFERENCES tax_rule(id) ON DELETE SET NULL,
    name_snapshot VARCHAR(160) NOT NULL,
    rate_percent_snapshot NUMERIC(7,4) NOT NULL CHECK (rate_percent_snapshot >= 0),
    amount NUMERIC(14,2) NOT NULL CHECK (amount >= 0)
);

CREATE TABLE invoice_discount_line (
    id UUID PRIMARY KEY,
    invoice_id UUID NOT NULL REFERENCES invoice(id) ON DELETE RESTRICT,
    discount_rule_id UUID NULL REFERENCES discount_rule(id) ON DELETE SET NULL,
    name_snapshot VARCHAR(160) NOT NULL,
    discount_type_snapshot VARCHAR(12) NOT NULL CHECK (discount_type_snapshot IN ('fixed', 'percentage')),
    value_snapshot NUMERIC(14,4) NOT NULL CHECK (value_snapshot > 0),
    amount NUMERIC(14,2) NOT NULL CHECK (amount > 0),
    currency CHAR(3) NOT NULL,
    UNIQUE (invoice_id, discount_rule_id)
);

CREATE TABLE discount_redemption (
    id UUID PRIMARY KEY,
    discount_rule_id UUID NOT NULL REFERENCES discount_rule(id) ON DELETE RESTRICT,
    invoice_id UUID NOT NULL REFERENCES invoice(id) ON DELETE RESTRICT,
    status VARCHAR(12) NOT NULL CHECK (status IN ('reserved', 'consumed', 'released')),
    reserved_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    consumed_at TIMESTAMPTZ NULL,
    UNIQUE (discount_rule_id, invoice_id)
);
CREATE INDEX discount_redemption_usage_idx ON discount_redemption(discount_rule_id, status);
CREATE INDEX discount_red_invoice_idx ON discount_redemption(invoice_id);

CREATE TABLE billing_run_item (
    id UUID PRIMARY KEY,
    billing_run_id UUID NOT NULL REFERENCES billing_run(id) ON DELETE CASCADE,
    subscription_id UUID NOT NULL REFERENCES subscription(id) ON DELETE RESTRICT,
    period_start DATE NOT NULL,
    invoice_id UUID NULL REFERENCES invoice(id) ON DELETE SET NULL,
    status VARCHAR(16) NOT NULL CHECK (status IN ('created', 'already_exists', 'skipped', 'failed')),
    error_message TEXT NOT NULL DEFAULT '',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (billing_run_id, subscription_id, period_start)
);

CREATE TABLE payment (
    id UUID PRIMARY KEY,
    invoice_id UUID NOT NULL REFERENCES invoice(id) ON DELETE RESTRICT,
    method VARCHAR(40) NOT NULL,
    amount NUMERIC(14,2) NOT NULL CHECK (amount > 0),
    currency CHAR(3) NOT NULL,
    status VARCHAR(12) NOT NULL DEFAULT 'posted' CHECK (status IN ('posted', 'void', 'refunded')),
    paid_at TIMESTAMPTZ NOT NULL,
    note TEXT NOT NULL DEFAULT '',
    recorded_by_id UUID NULL REFERENCES account_user(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX payment_invoice_status_idx ON payment(invoice_id, status);
CREATE INDEX payment_date_idx ON payment(paid_at);

CREATE TABLE password_reset_token (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES account_user(id) ON DELETE CASCADE,
    token_digest VARCHAR(128) NOT NULL UNIQUE,
    expires_at TIMESTAMPTZ NOT NULL,
    consumed_at TIMESTAMPTZ NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE audit_event (
    id UUID PRIMARY KEY,
    actor_id UUID NULL REFERENCES account_user(id) ON DELETE SET NULL,
    action VARCHAR(64) NOT NULL,
    entity_type VARCHAR(64) NOT NULL,
    entity_id UUID NULL,
    details JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX audit_event_entity_idx ON audit_event(entity_type, entity_id, created_at);
